declare(strict_types=1);require_once __DIR__.'/includes/header.php';require_login();$user=current_user();$downloads=load_json('downloads.json',[]);$history=array_values(array_filter($downloads,fn($d)=>is_array($d)&&($d['user_id']??null)===$user['id']));$latest=current_release();?><main class="container" style="padding:150px 0 100px"><div class="account-layout"><aside class="account-sidebar"><a class="active" href="<?= e(app_url('account.php')) ?>">Overview</a><a href="<?= e(app_url('download.php')) ?>">Downloads</a><a href="<?= e(app_url('logout.php')) ?>">Logout</a></aside><div class="account-main"><div class="account-welcome"><div class="status-pill">Account active</div><h2>Welcome back, <?= e((string)$user['username']) ?>.</h2><p>Your activity is stored securely on this server.</p></div><div class="metric-grid"><div class="metric"><span>Total downloads</span><strong><?= count($history) ?></strong></div><div class="metric"><span>Latest version</span><strong><?= e((string)($latest['version']??'—')) ?></strong></div><div class="metric"><span>Account age</span><strong><?= e(date('Y')-(int)date('Y',strtotime($user['created_at']))) ?></strong></div><div class="metric"><span>Platform</span><strong>Windows</strong></div></div><section class="card"><div class="admin-toolbar"><div><h3>Download history</h3><p>Every installer request is recorded here.</p></div><a class="button button-primary button-small" href="<?= e(app_url('download.php')) ?>">Download latest</a></div><div class="table-wrap"><table><thead><tr><th>Version</th><th>Platform</th><th>Architecture</th><th>Date</th><th>File</th></tr></thead><tbody><?php if(!$history):?><tr><td colspan=5><div class="empty-state"><div class="empty-icon">↓</div><h3>No downloads yet</h3><p>Your first installer will appear here.</p></div></td></tr><?php else:foreach(array_reverse($history) as $item):?><tr><td><?= e((string)release_by_id((string)$item['release_id'])['version']??'Unknown') ?></td><td>Windows</td><td><?= e((string)$item[